<?php
require "koneksi.php";$result=$conn->query("SELECT k.*,p.nama_pasien FROM kunjungan k JOIN pasien p ON p.id=k.id_pasien ORDER BY k.id DESC");
?><!DOCTYPE html><html lang="id"><head><meta charset="UTF-8"><meta name="viewport" content="width=device-width, initial-scale=1"><link href="https://cdn.jsdelivr.net/npm/bootstrap@5.3.3/dist/css/bootstrap.min.css" rel="stylesheet"><link href="style.css" rel="stylesheet"><title>Data Kunjungan</title></head><body><nav class="navbar navbar-dark bg-primary"><div class="container-fluid px-4"><a class="navbar-brand fw-bold" href="index.php">KlinikZakwan</a><a class="nav-link text-white" href="index.php">Data Pasien</a><span class="navbar-text ms-auto">Aplikasi KlinikZakwan Paket 3</span></div></nav><main class="container py-4"><h3>Data Kunjungan</h3><p class="text-muted">Daftar kunjungan pasien KlinikZakwan</p><div class="card shadow-sm"><div class="card-body table-responsive"><table class="table table-bordered table-striped"><thead class="table-primary"><tr><th>No</th><th>Nama Pasien</th><th>Tanggal</th><th>Keluhan</th></tr></thead><tbody><?php if($result->num_rows):$n=1;while($k=$result->fetch_assoc()):?><tr><td><?=$n++?></td><td><?=htmlspecialchars($k['nama_pasien'])?></td><td><?=htmlspecialchars($k['tanggal'])?></td><td><?=htmlspecialchars($k['keluhan']??'')?></td></tr><?php endwhile;else:?><tr><td colspan="4" class="text-center">Belum ada data kunjungan. Tabel ini disiapkan untuk data kunjungan.</td></tr><?php endif;?></tbody></table></div></div><a href="index.php" class="btn btn-primary mt-3">Kembali ke Data Pasien</a></main></body></html>